; The Gen 1 tutor's moves, and which Kanto species learned each by TM in Red/Blue.
; The learnsets come from pokered's base stats (data/pokemon/base_stats/*.asm, tmhm).

MACRO gen1_tutor_move
	dw \1
	DEF GEN1_TUTOR_\1 EQU NUM_GEN1_TUTOR_MOVES
	DEF NUM_GEN1_TUTOR_MOVES += 1
ENDM

MACRO gen1_tutor_learnset
; species, then its moves from Gen1TutorMoves: one bit each, in their order
	assert \1 == GEN1_TUTOR_LEARNSET_ROWS + 1, "\1 is out of order"
	DEF GEN1_TUTOR_LEARNSET_ROWS += 1
	for _gen1_tutor_byte, GEN1_TUTOR_LEARNSET_WIDTH
		DEF _gen1_tutor_bits_{d:_gen1_tutor_byte} = 0
	endr
	shift
	rept _NARG
		DEF _gen1_tutor_byte = GEN1_TUTOR_\1 / 8
		DEF _gen1_tutor_bits_{d:_gen1_tutor_byte} |= 1 << (GEN1_TUTOR_\1 % 8)
		shift
	endr
	for _gen1_tutor_byte, GEN1_TUTOR_LEARNSET_WIDTH
		db _gen1_tutor_bits_{d:_gen1_tutor_byte}
	endr
ENDM

	DEF NUM_GEN1_TUTOR_MOVES = 0
	DEF GEN1_TUTOR_LEARNSET_ROWS = 0

; The Gen 1 TM moves this game doesn't teach by TM, HM or tutor.
Gen1TutorMoves:
	gen1_tutor_move MEGA_PUNCH
	gen1_tutor_move RAZOR_WIND
	gen1_tutor_move SWORDS_DANCE
	gen1_tutor_move WHIRLWIND
	gen1_tutor_move MEGA_KICK
	gen1_tutor_move HORN_DRILL
