	gen1_tutor_move PAY_DAY
	gen1_tutor_move SUBMISSION
	gen1_tutor_move COUNTER
	gen1_tutor_move SEISMIC_TOSS
	gen1_tutor_move RAGE
	gen1_tutor_move MEGA_DRAIN
	gen1_tutor_move DRAGON_RAGE
	gen1_tutor_move FISSURE
	gen1_tutor_move TELEPORT
	gen1_tutor_move MIMIC
	gen1_tutor_move REFLECT
	gen1_tutor_move BIDE
	gen1_tutor_move METRONOME
	gen1_tutor_move SELFDESTRUCT
