	gen1_tutor_move SUBSTITUTE
	assert NUM_GEN1_TUTOR_MOVES == MAX_GEN1_TUTOR_MOVES
	DEF GEN1_TUTOR_LEARNSET_WIDTH EQU (NUM_GEN1_TUTOR_MOVES + 7) / 8

